export function blockOne() {
  const a = 100;
  const b = 200;
  const c = 300;
  const d = 400;
  const e = 500;
  if (a + b > c) {
    return a + b + c + d + e;
  }
  if (a + b + c > d) {
    return a + b + c + d;
  }
  return 0;
}

